import {feedbackLevel} from './visuals.js?v=2.3.1';
import {terminalIndices} from './terminals.js?v=2.2';
import {componentTerminal} from './visuals.js?v=2.3.1';

// Both representations use the same terminal coordinates and electrical identities.
const extents={battery:[-58,-32,58,32],lamp:[-58,-46,58,29],resistor:[-58,-19,58,19],switch:[-58,-39,58,24],spdt:[-58,-42,58,42],ammeter:[-58,-45,58,35],voltmeter:[-58,-45,58,35],rheostat:[-58,-58,51,31],motor:[-58,-33,58,37],bell:[-37,-36,37,58],heater:[-58,-28,58,28],capacitor:[-58,-29,58,29],inductor:[-58,-25,58,25],fuse:[-58,-17,58,17]};
const screw=(x,y,color='#b8c0c8')=>`<g transform="translate(${x} ${y})"><circle r="5.5" fill="${color}" stroke="#697580" stroke-width="1.2"/><path d="m-2.5 2.5 5-5" stroke="#52606d" stroke-width="1.2"/></g>`;
const lead=d=>`<path d="${d}" fill="none" stroke="#929da8" stroke-width="4"/><path d="${d}" fill="none" stroke="#dfe5e9" stroke-width="1.2"/>`;
const text=(c,x,y,value,size=8,color='#52606d')=>`<text x="${x}" y="${y}" transform="rotate(${-(c.angle??0)} ${x} ${y})" fill="${color}" stroke="none" text-anchor="middle" font-family="Arial,Microsoft YaHei,sans-serif" font-size="${size}">${value}</text>`;

export function physicalSymbol(c,{thumbnail=false,power=0,current=0,voltage=0}={}) {
  const id=`physical-${c.id??c.type}`,metal=`url(#${id}-metal)`,base=`url(#${id}-base)`,copper=`url(#${id}-copper)`,level=thumbnail?0:feedbackLevel(Math.abs(power),2);
  const defs=`<defs><linearGradient id="${id}-metal" x2="0" y2="1"><stop stop-color="#edf2f5"/><stop offset=".45" stop-color="#aab6c0"/><stop offset=".7" stop-color="#e0e7ec"/><stop offset="1" stop-color="#8796a3"/></linearGradient><linearGradient id="${id}-base" x2="0" y2="1"><stop stop-color="#405167"/><stop offset="1" stop-color="#253345"/></linearGradient><linearGradient id="${id}-copper" x2="0" y2="1"><stop stop-color="#e9bb7d"/><stop offset=".5" stop-color="#b97a3b"/><stop offset=".7" stop-color="#e4a96a"/><stop offset="1" stop-color="#98612e"/></linearGradient></defs>`;
  let body='';
  if(c.type==='battery')body=`<rect x="-47" y="-31" width="94" height="62" rx="8" fill="${base}" stroke="#1f2d40"/><rect x="-40" y="-24" width="80" height="48" rx="5" fill="#172433"/><rect x="-35" y="-20" width="70" height="40" rx="5" fill="#ddd6c4"/><path d="M-35-15q0-5 5-5H8v40h-38q-5 0-5-5Z" fill="#c77b4e"/><path d="M8-20h21q6 0 6 6v28q0 6-6 6H8Z" fill="#e4dfd0"/><path d="M-33-15H31" stroke="#fff" opacity=".38" stroke-width="4"/><rect x="-40" y="-7" width="5" height="14" rx="1" fill="${metal}"/>${lead('M-47 0h-7M47 0h7')}${text(c,-22,5,'+',14,'#fff8ee')}${text(c,23,5,'−',14)}${text(c,0,28,`${c.value??6} V`,7,'#cbd5e1')}`;
  else if(c.type==='lamp')body=`${level>.001?`<ellipse cx="0" cy="-14" rx="43" ry="43" fill="#ffca59" opacity="${.18*level}"/>`:''}<rect x="-46" y="1" width="92" height="26" rx="7" fill="#e6b96d" stroke="#b28b50"/><path d="M-40 6h80" stroke="#f9dfaa" stroke-width="2"/><ellipse cy="3" rx="19" ry="10" fill="#838a91"/><path d="M-14-1v11q14 9 28 0V-1" fill="${metal}" stroke="#7f8993"/><path d="M-14 2h28m-28 5h28" stroke="#788590" stroke-width="1.5"/><path d="M-13-5c0-7-11-13-11-25a24 24 0 0 1 48 0C24-18 13-12 13-5Z" fill="${level>.001?'#ffe39b':'#e9f2f6'}" fill-opacity="${.65+.35*level}" stroke="${level>.1?'#dfb55b':'#9db6c3'}" stroke-width="1.5"/><path d="M-8-7v-13m16 13v-13m-16 0 4-5 4 7 4-7 4 5" fill="none" stroke="${level>.1?'#ed9a28':'#81909b'}" stroke-width="${1.2+level}"/><path d="M-14-34q-5 5-4 10" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/>${lead('M-54 0h12M42 0h12')}${screw(-35,13)}${screw(35,13)}`;
  else if(c.type==='resistor')body=`${lead('M-54 0h28M28 0h26')}<path d="M-28-11q0-7 8-7h8l5 3H7l5-3h8q8 0 8 7v22q0 7-8 7h-8l-5-3H-7l-5 3h-8q-8 0-8-7Z" fill="#dfca9b" stroke="#ad956a"/><path d="M-17-16v32" stroke="#8c5937" stroke-width="6"/><path d="M-5-15v30" stroke="#292c36" stroke-width="6"/><path d="M7-15v30" stroke="#c77c3f" stroke-width="6"/><path d="M21-15v30" stroke="#d3ae4f" stroke-width="4"/><path d="M-24-12h48" stroke="#fff" stroke-opacity=".35" stroke-width="3"/>`;
  else if(c.type==='switch'||c.type==='spdt'){
    const spdt=c.type==='spdt',target=spdt?(c.position===2?24:-24):(c.closed?0:-29);
    body=`<rect x="-47" y="${spdt?-39:-22}" width="94" height="${spdt?78:44}" rx="6" fill="#b67c4f" stroke="#8e603f"/><rect x="-42" y="${spdt?-34:-17}" width="84" height="${spdt?68:34}" rx="3" fill="#d2a072"/><path d="M-39 ${spdt?-28:-12}h78" stroke="#e5bc94" stroke-width="2"/>${lead(spdt?'M-54 0h28M26-24h28M26 24h28':'M-54 0h28M26 0h28')}<rect x="-31" y="-8" width="14" height="16" rx="2" fill="${copper}"/><rect x="19" y="${spdt?-31:-7}" width="14" height="14" rx="2" fill="${copper}"/>${spdt?`<rect x="19" y="17" width="14" height="14" rx="2" fill="${copper}"/>`:''}<path d="M-24 0 26 ${target}" stroke="#806333" stroke-width="7" stroke-linecap="round"/><path d="M-24-2 26 ${target-2}" stroke="#e8d499" stroke-width="3" stroke-linecap="round"/><circle cx="-24" r="5" fill="${metal}"/><rect x="7" y="${target-6}" width="22" height="12" rx="4" fill="#4a535b" transform="rotate(${spdt?(c.position===2?26:-26):c.closed?0:-30} 18 ${target})"/>${spdt?text(c,-36,17,'C',8)+text(c,39,-15,'1',8)+text(c,39,34,'2',8):''}`;
  }else if(c.type==='ammeter'||c.type==='voltmeter'){
    const amp=c.type==='ammeter',value=amp?current:voltage,angle=-55+110*Math.max(-.08,Math.min(1,value/(amp?3:15)));
    body=`<rect x="-45" y="-43" width="90" height="76" rx="10" fill="${base}" stroke="#263549"/><rect x="-38" y="-36" width="76" height="49" rx="6" fill="#f6f2e8" stroke="#b5bec6"/><path d="M-29-4a31 31 0 0 1 58 0" fill="none" stroke="#88939e" stroke-width="1.1"/>${[-50,-25,0,25,50].map(a=>`<path d="M0-31v5" transform="translate(0 7) rotate(${a})" stroke="#697885" stroke-width="1"/>`).join('')}<path d="M0 7v-31" transform="rotate(${angle} 0 7)" stroke="#c65f51" stroke-width="1.5"/><circle cy="7" r="3" fill="#526371"/>${text(c,0,-7,amp?'A':'V',12)}${text(c,-28,6,'0',6)}${text(c,29,6,amp?'3':'15',6)}${text(c,0,26,amp?'直流电流表':'直流电压表',7,'#d6dfe7')}${lead('M-54 0h9M45 0h9')}<circle cx="-50" r="7" fill="#c96357" stroke="#9e4842"/><circle cx="50" r="7" fill="#354050" stroke="#1f2937"/>`;
  }else if(c.type==='rheostat'){
    const slider=-29+58*Math.max(0,Math.min(1,(c.value??20)/100));
    body=`<rect x="-46" y="17" width="95" height="12" rx="4" fill="#7c6758"/><path d="M-37-9v30m73-30v30" stroke="#b5c0c8" stroke-width="8"/><rect x="-38" y="-12" width="77" height="27" rx="7" fill="#c3bdac" stroke="#999080"/>${Array.from({length:23},(_,i)=>`<path d="M${-33+i*3}-11v25" stroke="#8e7460" stroke-width="1.3"/>`).join('')}<path d="M-41-29h84" stroke="#8e9ca9" stroke-width="5"/><path d="M-41-31h84" stroke="#e2e8ed" stroke-width="1.5"/><rect x="${slider-7}" y="-36" width="14" height="14" rx="3" fill="#3d515e" stroke="#233947"/><path d="M${slider}-24v13" stroke="#d6ad6f" stroke-width="4"/>${lead(`M-54 18h15V6M0-54v10H${slider}v10`)}${text(c,0,26,'滑动变阻器',6,'#f0e5d9')}`;
  }else if(c.type==='motor')body=`${lead('M-54 0h24M30 0h24')}<path d="M-25 17-33 34h66l-8-17" fill="#64818c" stroke="#48636e"/><rect x="-29" y="-28" width="58" height="55" rx="13" fill="${metal}" stroke="#7c909c"/><circle r="24" fill="#c9d6dd" stroke="#6d8593" stroke-width="2"/><circle r="18" fill="#90a7b4" stroke="#738d9d"/>${[-17,17].map(x=>screw(x,-18)).join('')}<circle r="4" fill="#dfe7ec"/>${text(c,0,34,'直流电动机',6,'#e0ecee')}`;
  else if(c.type==='bell')body=`<rect x="-33" y="-32" width="66" height="81" rx="7" fill="#b7845e" stroke="#8c6549"/><rect x="-27" y="10" width="23" height="25" rx="4" fill="#4e5e69"/><path d="M-24 15h17m-17 5h17m-17 5h17m-17 5h17" stroke="#ba8552" stroke-width="2"/><path d="M-1 33h22V-1" fill="none" stroke="#74818b" stroke-width="3"/><circle class="physical-bell-hammer" cx="21" cy="-4" r="5" fill="#74818b"/><circle class="physical-bell-dome" cy="-9" r="25" fill="${metal}" stroke="#7a8a97" stroke-width="1.5"/><path d="M-17-20q15-15 31 1" fill="none" stroke="#fff" stroke-opacity=".65" stroke-width="2"/><circle cy="-9" r="4" fill="#81929f"/>${lead('M-14 43v11M14 43v11')}${screw(-14,43)}${screw(14,43)}`;
  else if(c.type==='heater')body=`${lead('M-54 0h12M42 0h12')}<rect x="-42" y="-25" width="84" height="50" rx="7" fill="#e5ddd0" stroke="#b5ada1"/><rect x="-34" y="-17" width="68" height="34" rx="4" fill="#c7bca9"/>${level>.001?`<rect x="-32" y="-15" width="64" height="30" rx="5" fill="#f28c52" opacity="${level*.5}"/>`:''}<path d="M-39 0h9l5-12 10 24 10-24 10 24 10-24 10 24 5-12h9" fill="none" stroke="${level>.01?`rgb(${Math.round(139+110*level)},${Math.round(126-42*level)},${Math.round(111-66*level)})`:'#8b7e6f'}" stroke-width="3.3" stroke-linejoin="round"/>`;
  else if(c.type==='capacitor')body=`${lead('M-54 0h29M25 0h29')}<rect x="-27" y="-25" width="54" height="50" rx="8" fill="#55748f" stroke="#365670"/><ellipse cx="-23" rx="6" ry="25" fill="#809bad" stroke="#456b82"/><path d="M-14-23v46" stroke="#c2d3dd" stroke-width="8"/><path d="M-19-17v7m-3-3h6m-3 13v7m-3-3h6" stroke="#42647b" stroke-width="1.2"/><path d="M-3-20h22" stroke="#97afc0" stroke-opacity=".6" stroke-width="3"/>${text(c,9,4,`${c.value??100}`,9,'#e4eef3')}${text(c,9,16,'μF',7,'#d0dfe9')}`;
  else if(c.type==='inductor')body=`${lead('M-54 0h24M30 0h24')}<rect x="-37" y="-22" width="74" height="44" rx="6" fill="#66717b" stroke="#465460"/><rect x="-30" y="-24" width="60" height="48" rx="6" fill="${copper}"/>${Array.from({length:15},(_,i)=>`<path d="M${-26+i*3.7}-22v44" stroke="#895b35" stroke-width="1.3"/>`).join('')}<path d="M-27-17h54" stroke="#f5cf8f" stroke-opacity=".65" stroke-width="2"/><rect x="-39" y="-24" width="10" height="48" rx="3" fill="${metal}"/><rect x="29" y="-24" width="10" height="48" rx="3" fill="${metal}"/>`;
  else if(c.type==='fuse')body=`${lead('M-54 0h24M24 0h30')}<rect x="-30" y="-14" width="60" height="28" rx="5" fill="${c.blown?'#e4dbd8':'#e7f1f4'}" fill-opacity=".7" stroke="#a6bbc6"/><path d="M-22 0h${c.blown?'12m20 0h12':'44'}" stroke="${c.blown?'#78716c':'#b39360'}" stroke-width="1.8"/>${c.blown?'<path d="m-5-6 10 12m-10 0L5-6" stroke="#b65d50" stroke-width="1.5"/>':''}<rect x="-32" y="-15" width="13" height="30" rx="3" fill="${metal}" stroke="#8799a6"/><rect x="19" y="-15" width="13" height="30" rx="3" fill="${metal}" stroke="#8799a6"/><path d="M-17-9h34" stroke="#fff" stroke-width="2" opacity=".8"/>`;
  return `${defs}<g class="physical-part ${c.type==='bell'&&level>.001?'is-powered':''}" stroke-linecap="round" stroke-linejoin="round" stroke-width="1">${body}</g>`;
}

export function physicalHitBounds(c) {
  const [left,top,right,bottom]=extents[c.type]??[-58,-35,58,35],angle=(c.angle??0)*Math.PI/180,points=[];
  for(const x of [left,right])for(const y of [top,bottom])points.push({x:c.x+x*Math.cos(angle)-y*Math.sin(angle),y:c.y+x*Math.sin(angle)+y*Math.cos(angle)});
  const x=Math.min(...points.map(p=>p.x))-3,y=Math.min(...points.map(p=>p.y))-3;
  return {x,y,width:Math.max(...points.map(p=>p.x))+3-x,height:Math.max(...points.map(p=>p.y))+3-y};
}
export function physicalLabelOffset(c){const box=physicalHitBounds(c);return {x:0,y:box.y+box.height-c.y+15};}
export function physicalBounds(c){const box=physicalHitBounds(c),label=physicalLabelOffset(c),points=terminalIndices(c.type).map(i=>componentTerminal(c,i)),left=Math.min(box.x,...points.map(p=>p.x),c.x-44)-8,top=Math.min(box.y,...points.map(p=>p.y))-8;return {x:left,y:top,width:Math.max(box.x+box.width,...points.map(p=>p.x),c.x+44)+8-left,height:Math.max(box.y+box.height,...points.map(p=>p.y),c.y+label.y+21)+8-top};}
export function physicalThumbnail(type,scope='library'){const e=extents[type],view=`${e[0]-5} ${e[1]-5} ${e[2]-e[0]+10} ${e[3]-e[1]+10}`;return `<svg viewBox="${view}" aria-hidden="true">${physicalSymbol({id:`${scope}-${type}`,type,value:20,angle:0,closed:false,position:1},{thumbnail:true})}</svg>`;}
